// Cross-checks the Dart science core against SPICE truth vectors generated by
// `python -m lunarsp.fixtures` (spkcpo with the observer on the lunar surface).
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:polar_horizon/core/ephemeris.dart';
import 'package:polar_horizon/core/geo.dart';
import 'package:polar_horizon/core/horizon.dart';
import 'package:polar_horizon/core/visibility.dart';

Future<List<int>> _load(String p) => File('assets/data/$p').readAsBytes();

void main() {
  final truth = jsonDecode(File('test/fixtures/spice_truth.json').readAsStringSync()) as Map<String, dynamic>;
  final cases = (truth['azel'] as List).cast<Map<String, dynamic>>();

  group('topocentric az/el vs SPICE spkcpo', () {
    late Ephemeris eph;
    setUpAll(() async {
      final repo = EphemerisRepository((p) async => Uint8List.fromList(await _load(p)));
      final m = await repo.manifest();
      eph = await repo.range(m.startUnixMs.toDouble(), m.endUnixMs.toDouble());
    });

    for (final body in ['sun', 'earth']) {
      test('$body: ${cases.length} random sites/epochs within 0.01 arcmin', () {
        var maxSep = 0.0, sumSq = 0.0, maxRangeRel = 0.0;
        for (final c in cases) {
          final obs = Observer((c['lat'] as num).toDouble(), (c['lon'] as num).toDouble(), (c['h'] as num).toDouble());
          final t = (c['unixMs'] as num).toDouble();
          final v = body == 'sun' ? eph.sun(t) : eph.earth(t);
          final got = obs.look(v);
          final ref = (c[body] as List).cast<num>();
          final sep = angularSepArcmin(got.az, got.el, ref[0].toDouble(), ref[1].toDouble());
          maxSep = math.max(maxSep, sep);
          sumSq += sep * sep;
          maxRangeRel = math.max(maxRangeRel, ((got.range - ref[2]) / ref[2]).abs());
        }
        final rms = math.sqrt(sumSq / cases.length);
        // ignore: avoid_print
        print('$body: max ${maxSep.toStringAsFixed(5)}\' rms ${rms.toStringAsFixed(5)}\' max range rel err ${maxRangeRel.toStringAsExponential(2)}');
        expect(maxSep, lessThan(0.01));
        expect(maxRangeRel, lessThan(1e-6));
      });
    }
  });

  group('visible disk fraction vs Python reference', () {
    final fr = (truth['fraction'] as List).cast<Map<String, dynamic>>();
    final step = (truth['maskAzStepDeg'] as num).toDouble();
    test('${fr.length} jagged-horizon cases match to 1e-9', () {
      for (final c in fr) {
        final mask = HorizonMask(step, Float64List.fromList([for (final v in (c['mask'] as List)) (v as num).toDouble()]));
        final f = visibleFraction((c['az'] as num).toDouble(), (c['el'] as num).toDouble(), (c['rho'] as num).toDouble(), mask);
        expect(f, closeTo((c['fraction'] as num).toDouble(), 1e-9));
      }
    });
  });
}
